// ---------------------------------------------------------------------
// 전환 기한 (TransitionTimeline) — Regulation (EU) 2024/1860
// ---------------------------------------------------------------------
export interface TransitionMilestone {
  cls: string; // "Class D"
  deadline: string; // "2027.12"
  detail?: string; // 부가 마일스톤
  tone: TagTone;
}

export const transitions: TransitionMilestone[] = [
  {
    cls: "A 비멸균",
    deadline: "2022.5.26",
