    deadline: "2028.12",
    detail: "NB 신청 2026.5.26 · 서면계약 2026.9.26",
    tone: "warning",
  },
  {
    cls: "Class B · A멸균",
    deadline: "2029.12",
    detail: "가장 긴 전환 기간",
    tone: "info",
  },
