/** 전환 기한 연장은 자동이 아니다 — 아래 조건을 모두 충족해야 한다. */
export const transitionConditions: string[] = [
  "IVDD 적합성을 계속 유지할 것",
  "2025.5.26까지 Art.10(8) QMS를 갖출 것",
