(() => {
  const dlg = document.querySelector('[role="dialog"]');
  if (!dlg) return { dialogOpen:false };
  const docBtn = dlg.querySelector('a[href="/doc/7"]');
  const conceptLinks = Array.from(dlg.querySelectorAll('a[href^="/wiki/"]')).map(a=>({href:a.getAttribute('href'), text:a.textContent.trim()}));
  return {
    path: location.pathname,
    title: document.getElementById('detail-title')?.textContent,
    hasDocButton: !!docBtn,
    docButtonText: docBtn?.textContent.trim(),
    conceptLinkCount: conceptLinks.length,
    conceptLinks: conceptLinks.slice(0,12),
  };
})()

