(() => {
  // verify mindmap structure: root, group spines with colored borders, elbows, leaves
  const groupSpines = Array.from(document.querySelectorAll('main .relative[style*="border-left"]'));
  const elbows = document.querySelectorAll('main span[style*="border-top"]').length;
  const leaves = document.querySelectorAll('main h3').length;
  const templateLinks = document.querySelectorAll('main a[href^="/doc/"]').length;
  // sample a group node tint bg
  const groupNode = document.querySelector('main div[style*="border-left: 4px"]');
  return {
    path: location.pathname,
    rootText: document.querySelector('main')?.querySelector('div')?.textContent?.slice(0,30),
    spineElements: groupSpines.length,
    elbowConnectors: elbows,
    leafHeadings: leaves,
    templateLinks,
    sampleGroupBorder: groupNode ? getComputedStyle(groupNode).borderLeftColor : null,
    horizontalScroll: document.documentElement.scrollWidth > window.innerWidth+1,
  };
})()

(() => {
  // per-group colors
  const groupNodes = Array.from(document.querySelectorAll('main div[style*="border-left: 4px"]'));
  const colors = groupNodes.map(n => getComputedStyle(n).borderLeftColor);
  // alignment check: first group spine + first leaf elbow + first leaf card
  const firstSpine = document.querySelector('main .relative[style*="border-left: 2px"]');
  const spineRect = firstSpine?.getBoundingClientRect();
  const firstElbow = document.querySelector('main span[style*="border-top"]');
  const elbowRect = firstElbow?.getBoundingClientRect();
  return {
    groupBorderColors: colors,
    spineLeftX: spineRect ? Math.round(spineRect.left) : null,
    elbowLeftX: elbowRect ? Math.round(elbowRect.left) : null,
    elbowRightX: elbowRect ? Math.round(elbowRect.right) : null,
    elbowWidth: elbowRect ? Math.round(elbowRect.width) : null,
  };
})()

(() => ({
  viewport: window.innerWidth,
  pageHorizontalScroll: document.documentElement.scrollWidth > window.innerWidth+1,
  leaves: document.querySelectorAll('main h3').length,
  // the tree scroll container
  treeOverflowsInternally: (() => { const c = document.querySelector('main div[style*="overflow-x"]'); return c ? c.scrollWidth > c.clientWidth : null; })(),
}))()

