          <input
            ref={fileRef}
            type="file"
            accept=".docx"
            onChange={onFile}
            disabled={busy}
            className="hidden"
          />
        </label>
      </div>

      {/* 상태 */}
      {state.kind !== "idle" && (
        <div
          className="mt-3 flex items-start gap-2 rounded-[var(--r-sm)]"
          style={{
            fontSize: "var(--t-sm)",
            padding: "8px 10px",
            background:
              state.kind === "error"
                ? "var(--danger-bg)"
                : state.kind === "done"
                  ? "var(--success-bg)"
                  : "var(--surface-2)",
            color:
              state.kind === "error"
                ? "var(--danger)"
                : state.kind === "done"
                  ? "var(--success)"
                  : "var(--text-muted)",
          }}
        >
          {state.kind === "busy" && <Loader2 size={16} className="mt-0.5 shrink-0 animate-spin" aria-hidden />}
          {state.kind === "done" && <Check size={16} className="mt-0.5 shrink-0" aria-hidden />}
          {state.kind === "error" && <AlertCircle size={16} className="mt-0.5 shrink-0" aria-hidden />}
          <span>{state.msg}</span>
        </div>
      )}
    </div>
  );
}

