(async () => {
  try {
    const m = await import('/src/lib/docx.ts');
    const doc = {
      id:'test', stationId:7, docTitle:'위험관리 계획(테스트)',
      purpose:'테스트 목적입니다', refs:['ISO 14971','Annex I'],
      sections:[{heading:'1. 범위', guidance:'범위 안내', placeholder:'표준: [____]'}],
      checklist:['추적되는가','승인됐는가'], relatedConceptSlugs:[]
    };
    // 1) sample (has placeholders)
    const sample = await m.generateSampleDocx(doc);
    // 2) fill the sample -> should be 'filled'
    const filled = await m.fillUploadedDocx(await sample.arrayBuffer(), doc);
    // 3) plain docx without placeholders -> 'appended'
    const dx = await import('docx');
    const plain = await dx.Packer.toBlob(new dx.Document({sections:[{children:[new dx.Paragraph({children:[new dx.TextRun('회사 서식 본문')]})]}]}));
    const appended = await m.fillUploadedDocx(await plain.arrayBuffer(), doc);
    // verify filled content contains our data
    const PizZip = (await import('pizzip')).default;
    const zip = new PizZip(await filled.blob.arrayBuffer());
    const xml = zip.file('word/document.xml').asText();
    return {
      sampleBytes: sample.size,
      filledMode: filled.mode, filledBytes: filled.blob.size,
      appendedMode: appended.mode, appendedBytes: appended.blob.size,
      filledHasTitle: xml.includes('위험관리 계획(테스트)'),
      filledHasChecklist: xml.includes('추적되는가'),
      filledNoRawPlaceholder: !xml.includes('{docTitle}'),
    };
  } catch(e) { return { error: e.message, stack: (e.stack||'').slice(0,300) }; }
})()

