input.expression:
(async () => {
  const tree = await import('/src/data/docTree.ts');
  const docs = await import('/src/data/documents.ts');
  const con = await import('/src/data/concepts.ts');
  const sta = await import('/src/data/stations.ts');
  const issues = [];
  const leaves = tree.allLeaves();
  const ids = leaves.map(l=>l.id);

  // 1) duplicate leaf ids
  const dup = ids.filter((id,i)=>ids.indexOf(id)!==i);
  if (dup.length) issues.push("중복 문서 id: "+[...new Set(dup)].join(", "));

  // 2) every leaf resolves + has rationale/knowledge/prereqs + valid stationId
  let noRat=[],noKno=[],noPre=[],badStation=[],noResolve=[];
  for (const l of leaves) {
    const d = docs.resolveDoc(l.id);
    if (!d) { noResolve.push(l.id); continue; }
    if (!d.rationale) noRat.push(l.id);
    if (!d.knowledge || !d.knowledge.length) noKno.push(l.id);
    if (!d.prerequisites || !d.prerequisites.length) noPre.push(l.id);
    if (!sta.stations.find(s=>s.id===l.stationId)) badStation.push(l.id);
  }
  if (noResolve.length) issues.push("resolve 실패: "+noResolve.join(", "));
  if (noRat.length) issues.push("취지 없음: "+noRat.join(", "));
  if (noKno.length) issues.push("사전지식 없음: "+noKno.join(", "));
  if (noPre.length) issues.push("준비물 없음: "+noPre.join(", "));
  if (badStation.length) issues.push("잘못된 stationId: "+badStation.join(", "));

  // 3) rationale/knowledge keys that don't match any leaf (orphans)
  const ratOrphan = Object.keys(tree.docRationale).filter(k=>!ids.includes(k));
  const knoOrphan = Object.keys(tree.docKnowledge).filter(k=>!ids.includes(k));
  if (ratOrphan.length) issues.push("고아 취지 키: "+ratOrphan.join(", "));
  if (knoOrphan.length) issues.push("고아 지식 키: "+knoOrphan.join(", "));

  // 4) primaryDocIdForStation valid for all 11 stations
  let badPrimary=[];
  for (const s of sta.stations) { const pid=tree.primaryDocIdForStation(s.id); if(!ids.includes(pid)) badPrimary.push(s.id+"→"+pid); }
  if (badPrimary.length) issues.push("정거장 대표문서 깨짐: "+badPrimary.join(", "));

  // 5) concept cross-links
  const slugs = con.concepts.map(c=>c.slug);
  let badRelSta=[],badRelCon=[];
  for (const c of con.concepts) {
    for (const sid of c.relatedStationIds) if(!sta.stations.find(s=>s.id===sid)) badRelSta.push(c.slug+"→"+sid);
    for (const cs of c.relatedConceptSlugs) if(!slugs.includes(cs)) badRelCon.push(c.slug+"→"+cs);
  }
  if (badRelSta.length) issues.push("개념→정거장 깨짐: "+badRelSta.join(", "));
  if (badRelCon.length) issues.push("개념→개념 깨짐: "+badRelCon.join(", "));

  // 6) inline {{slug|label}} links in station & concept bodies
  const RE=/\{\{([^}|]+)\|[^}]+\}\}/g;
  const badInline=[];
  const scan=(text,where)=>{let m;RE.lastIndex=0;while((m=RE.exec(text))){const sl=m[1].trim();if(!slugs.includes(sl))badInline.push(where+":"+sl);}};
  for (const s of sta.stations){ s.body.forEach(b=>scan(b,"St"+s.id)); if(s.note)scan(s.note,"St"+s.id+"note"); }
  for (const c of con.concepts){ c.body.forEach(b=>scan(b,c.slug)); }
  if (badInline.length) issues.push("본문 개념링크 깨짐: "+badInline.join(", "));

  // 7) document relatedConceptSlugs
  const badDocCon=[];
  for (const d of docs.documents){ for(const cs of (d.relatedConceptSlugs||[])) if(!slugs.includes(cs)) badDocCon.push(d.id+"→"+cs); }
  if (badDocCon.length) issues.push("문서→개념 깨짐: "+badDocCon.join(", "));

  return {
    counts: { leaves: leaves.length, stations: sta.stations.length, concepts: con.concepts.length, detailedDocs: docs.documents.length },
    issueCount: issues.length,
    issues,
  };
})()

