(() => {
  const dlg = document.querySelector('[role="dialog"]');
  if (!dlg) return { dialogOpen:false };
  // find the doc list section
  const header = Array.from(dlg.querySelectorAll('span')).find(s=>/이 단계에서 써야 할 문서/.test(s.textContent));
  const listBox = header?.closest('div')?.parentElement;
  const docLinks = listBox ? Array.from(listBox.querySelectorAll('a[href^="/doc/"]')) : [];
  return {
    path: location.pathname,
    detailTitle: document.getElementById('detail-title')?.textContent,
    hasDocListHeader: !!header,
    countBadge: header?.parentElement?.querySelector('span:last-child')?.textContent,
    docLinkCount: docLinks.length,
    firstFew: docLinks.slice(0,4).map(a=>({href:a.getAttribute('href'), title:a.textContent.trim().slice(0,20)})),
  };
})()

