    circle.dispatchEvent(new MouseEvent('click',{bubbles:true, view:window}));
    setTimeout(() => {
      const dlg = document.querySelector('[role="dialog"]');
      const header = dlg && Array.from(dlg.querySelectorAll('span')).find(s=>/이 단계에서 써야 할 문서/.test(s.textContent));
      const docLinks = dlg ? dlg.querySelectorAll('a[href^="/doc/"]').length : 0;
      res({
        path: location.pathname,
        dialogOpen: !!dlg,
        title: document.getElementById('detail-title')?.textContent,
        docListCount: header?.parentElement?.querySelector('span:last-child')?.textContent,
        docLinks,
      });
    }, 250);
  }, 250));
})()

