input.expression:
(async () => {
  const t = Date.now();
  const tree = await import('/src/data/docTree.ts?t='+t);
  const docs = await import('/src/data/documents.ts?t='+t);
  const ids = tree.allLeaves().map(l=>l.id);
  const issues = [];
  // completeness for all docs
  let bad=[];
  for (const l of ids) {
    const d = docs.resolveDoc(l);
    if (!d) { issues.push("resolve fail "+l); continue; }
    if (!d.rationale) bad.push("rat:"+l);
    if (!d.knowledge?.length) bad.push("kno:"+l);
    if (!d.prerequisites?.length) bad.push("pre:"+l);
    if (!d.difficulty||!d.importance) bad.push("meta:"+l);
  }
  if (bad.length) issues.push("불완전: "+bad.join(", "));
  // order coverage
  const orderIds = tree.docOrder.flatMap(s=>s.docIds);
  const dup=orderIds.filter((x,i)=>orderIds.indexOf(x)!==i);
  const missing=ids.filter(x=>!orderIds.includes(x));
  const unknown=orderIds.filter(x=>!ids.includes(x));
  if (dup.length) issues.push("순서 중복: "+[...new Set(dup)]);
  if (missing.length) issues.push("순서 누락: "+missing);
  if (unknown.length) issues.push("순서 미지정id: "+unknown);
  // dup ids
  const iddup = ids.filter((x,i)=>ids.indexOf(x)!==i);
  if (iddup.length) issues.push("문서 id 중복: "+[...new Set(iddup)]);
  return { totalDocs: ids.length, orderedDocs: orderIds.length, steps: tree.docOrder.length, newDocsResolve: ['cybersecurity','clinical-performance-study-plan','qms-software-validation'].map(id=>({id, ok: !!docs.resolveDoc(id)})), issueCount: issues.length, issues };
})()

