(async () => {
  const t = Date.now();
  const tree = await import('/src/data/docTree.ts?t='+t);
  const ids = new Set(tree.allLeaves().map(l=>l.id));
  // validate every prepDocs id exists, and self-reference check
  const bad = [], selfRef = [];
  for (const [id, arr] of Object.entries(tree.docPrep)) {
    if (!ids.has(id)) bad.push("key:"+id);
    for (const p of arr) { if (!ids.has(p)) bad.push(id+"→"+p); if (p===id) selfRef.push(id); }
  }
  const covered = Object.keys(tree.docPrep).length;
  return { totalDocs: ids.size, prepKeys: covered, allDocsHaveKey: covered===ids.size, brokenRefs: bad, selfRefs: selfRef };
})()

