(() => {
  const body = document.querySelector('main')?.innerText || '';
  const certSec = document.querySelector('section[aria-label="IVDR 인증의 전체 구조"]');
  const h1 = document.querySelector('h1')?.innerText;
  return {
    deletedPhraseGone: !/글을 읽지 않고도 한눈에/.test(body),
    h1: h1,
    hasCertInfographic: !!certSec,
    certIsFirst: document.querySelector('main')?.firstElementChild?.querySelector('section[aria-label="IVDR 인증의 전체 구조"]') ? true : (document.querySelector('main > div:first-child section[aria-label="IVDR 인증의 전체 구조"]')?true:false),
    statsNumbers: certSec ? Array.from(certSec.querySelectorAll('.font-extrabold')).map(e=>e.textContent).filter(t=>/^\d+$/.test(t)).slice(0,4) : [],
  };
})()

(() => {
  // count 공통 badges + verify a shared vs CE-only card border
  const badges = Array.from(document.querySelectorAll('main span')).filter(s=>/공통$/.test(s.textContent.trim()) && /ISO/.test(s.textContent)).length;
  // find risk-management-plan card (shared) and classification-rationale (CE only)
  const findCard = (docId) => {
    const link = document.querySelector(`main a[href="/doc/${docId}"]`);
    let el = link; while (el && !(el.style && el.style.border && el.style.border.includes('solid'))) el = el.parentElement;
    return el ? getComputedStyle(el).borderTopWidth + ' ' + getComputedStyle(el).borderTopColor : null;
  };
  return {
    sharedBadgeCount: badges,
    riskPlanBorder: findCard('risk-management-plan'),
    classificationBorder: findCard('classification-rationale'),
  };
})()

