import { Link } from "react-router-dom";
import { ArrowUpRight, Layers, Globe } from "lucide-react";
import { leafById, colorForLeaf } from "../data/docTree";
import {
  ceOnlyDocIds,
  sharedDocIds,
  fdaOnlyItems,
  mdsapMarkets,
} from "../data/schemes";

function DocChip({ id, link = true }: { id: string; link?: boolean }) {
  const l = leafById(id);
  if (!l) return null;
  const c = `var(${colorForLeaf(id)})`;
  const inner = (
    <>
      <span aria-hidden className="inline-block shrink-0 rounded-full" style={{ width: 7, height: 7, background: c }} />
      <span className="font-semibold text-text" style={{ fontSize: "var(--t-xs)" }}>{l.title}</span>
      {link && <ArrowUpRight size={12} style={{ color: "var(--text-subtle)" }} aria-hidden />}
    </>
  );
  const style = { border: "1px solid var(--border)", boxShadow: "var(--shadow-card)", padding: "4px 10px" } as const;
  return link ? (
    <Link to={`/doc/${id}`} className="inline-flex items-center gap-1.5 rounded-[var(--r-full)] bg-bg hover:bg-surface" style={style}>
      {inner}
    </Link>
  ) : (
    <span className="inline-flex items-center gap-1.5 rounded-[var(--r-full)] bg-bg" style={style}>{inner}</span>
  );
}

/** 규제 스킴 간 문서 중복(재사용) — 벤다이어그램 + 그룹별 문서. */
export function SchemeOverlap() {
  const shared = sharedDocIds();
  const nShared = shared.length;
  const nCe = ceOnlyDocIds.length;

  return (
    <div style={{ marginTop: "var(--s-6)" }}>
      <p className="text-text-muted" style={{ fontSize: "var(--t-sm)", marginBottom: "var(--s-5)", maxWidth: 760 }}>
        ISO 13485 QMS는 모든 스킴의 공통 기반이고, MDSAP는 그 QMS를 5개국 단일 심사로 묶습니다.
        CE(IVDR)·FDA는 같은 기반 위에 시장별 문서를 더합니다. <strong className="text-text">한 번 만들어 여러 스킴에 재사용</strong>되는 문서가 대부분입니다.
      </p>

      {/* ── 벤다이어그램 ── */}
      <div style={{ overflowX: "auto" }}>
        <svg viewBox="0 0 880 640" role="img" aria-label="규제 스킴별 문서 중복 벤다이어그램"
          style={{ width: "100%", minWidth: 600, height: "auto", display: "block" }}>
          {/* MDSAP 외곽 기반 (ISO 13485를 5개국 단일 심사로 감쌈) */}
          <rect x="34" y="352" width="812" height="262" rx="32" fill="var(--p5-tint)" stroke="var(--p5)" strokeWidth="2.5" />
          <text x="58" y="392" style={{ fontSize: 17, fontWeight: 800, fill: "var(--p5)" }}>MDSAP</text>
          <text x="440" y="590" textAnchor="middle" style={{ fontSize: 13, fontWeight: 700, fill: "var(--p5)" }}>
            MDSAP — {mdsapMarkets.join(" · ")} 단일 심사
          </text>
          {/* ISO 13485 내부 기반 (MDSAP 안에 포함) */}
          <rect x="150" y="402" width="580" height="118" rx="22" fill="var(--p3-tint)" stroke="var(--p3)" strokeWidth="2" />
          <text x="440" y="452" textAnchor="middle" style={{ fontSize: 19, fontWeight: 800, fill: "var(--p3)" }}>ISO 13485</text>
          <text x="440" y="478" textAnchor="middle" style={{ fontSize: 12, fontWeight: 700, fill: "var(--text-muted)" }}>QMS 공통 기반</text>

          {/* CE / FDA 원 (반투명 → 겹침이 진해짐) */}
          <circle cx="330" cy="250" r="198" fill="var(--p2)" fillOpacity="0.16" stroke="var(--p2)" strokeWidth="2.5" />
          <circle cx="550" cy="250" r="198" fill="var(--p4)" fillOpacity="0.16" stroke="var(--p4)" strokeWidth="2.5" />

          {/* 제목 */}
          <text x="190" y="78" textAnchor="middle" style={{ fontSize: 20, fontWeight: 800, fill: "var(--p2)" }}>CE / IVDR</text>
          <text x="190" y="100" textAnchor="middle" style={{ fontSize: 12, fontWeight: 600, fill: "var(--text-muted)" }}>EU 시장</text>
          <text x="690" y="78" textAnchor="middle" style={{ fontSize: 20, fontWeight: 800, fill: "var(--p4)" }}>FDA</text>
          <text x="690" y="100" textAnchor="middle" style={{ fontSize: 12, fontWeight: 600, fill: "var(--text-muted)" }}>US 시장</text>

          {/* CE 전용 (왼쪽 초승달) */}
          <text x="205" y="210" textAnchor="middle" style={{ fontSize: 13, fontWeight: 800, fill: "var(--p2)" }}>CE 전용 {nCe}</text>
          {["GSPR · 분류(Annex VIII)", "DoC · SSP · PER", "EUDAMED · UDI · PRRC", "NB · EU 대리인"].map((t, i) => (
            <text key={i} x="205" y={236 + i * 22} textAnchor="middle" style={{ fontSize: 12, fontWeight: 600, fill: "var(--text)" }}>{t}</text>
          ))}

          {/* FDA 전용 (오른쪽 초승달) */}
          <text x="678" y="210" textAnchor="middle" style={{ fontSize: 13, fontWeight: 800, fill: "var(--p4)" }}>FDA 전용</text>
          {["510(k)/PMA", "QMSR · FDA 등록", "GUDID · US agent"].map((t, i) => (
            <text key={i} x="678" y={236 + i * 22} textAnchor="middle" style={{ fontSize: 12, fontWeight: 600, fill: "var(--text)" }}>{t}</text>
          ))}

          {/* 공통(겹침) */}
          <text x="440" y="206" textAnchor="middle" style={{ fontSize: 15, fontWeight: 800, fill: "var(--text)" }}>공통 재사용</text>
          <text x="440" y="246" textAnchor="middle" style={{ fontSize: 40, fontWeight: 900, fill: "var(--accent)" }}>{nShared}</text>
          {["QMS · 설계관리", "위험관리 · 공정", "기술 · 성능 증거"].map((t, i) => (
            <text key={i} x="440" y={278 + i * 20} textAnchor="middle" style={{ fontSize: 12, fontWeight: 700, fill: "var(--text-muted)" }}>{t}</text>
          ))}
        </svg>
      </div>

      {/* ── 그룹별 문서 ── */}
      <div className="flex flex-col" style={{ gap: "var(--s-5)", marginTop: "var(--s-6)" }}>
        {/* 공통 */}
        <section>
          <div className="flex items-center gap-2" style={{ marginBottom: "var(--s-3)" }}>
            <Layers size={18} style={{ color: "var(--accent)" }} aria-hidden />
            <h3 className="font-extrabold text-text" style={{ fontSize: "var(--t-lg)" }}>공통 재사용 문서</h3>
            <span className="rounded-full font-bold text-text-on-color" style={{ background: "var(--accent)", fontSize: "var(--t-xs)", padding: "1px 9px" }}>{nShared}</span>
            <span className="text-text-subtle" style={{ fontSize: "var(--t-xs)" }}>ISO 13485 · MDSAP · CE · FDA 두루 재사용 (내용·서식은 시장별 상이)</span>
          </div>
          <div className="flex flex-wrap gap-2">
            {shared.map((id) => <DocChip key={id} id={id} />)}
          </div>
        </section>

        {/* CE 전용 */}
        <section>
          <div className="flex items-center gap-2" style={{ marginBottom: "var(--s-3)" }}>
            <span className="inline-block rounded-full" style={{ width: 14, height: 14, background: "var(--p2)" }} aria-hidden />
            <h3 className="font-extrabold text-text" style={{ fontSize: "var(--t-lg)" }}>CE / IVDR 전용</h3>
            <span className="rounded-full font-bold text-text-on-color" style={{ background: "var(--p2)", fontSize: "var(--t-xs)", padding: "1px 9px" }}>{nCe}</span>
            <span className="text-text-subtle" style={{ fontSize: "var(--t-xs)" }}>EU 시장 고유</span>
          </div>
          <div className="flex flex-wrap gap-2">
            {ceOnlyDocIds.map((id) => <DocChip key={id} id={id} />)}
          </div>
        </section>

        {/* FDA 전용 (참고) */}
        <section>
          <div className="flex items-center gap-2" style={{ marginBottom: "var(--s-3)" }}>
            <Globe size={18} style={{ color: "var(--p4)" }} aria-hidden />
            <h3 className="font-extrabold text-text" style={{ fontSize: "var(--t-lg)" }}>FDA(US) 전용 — 참고</h3>
            <span className="text-text-subtle" style={{ fontSize: "var(--t-xs)" }}>우리 IVDR 문서셋 밖 · 미국 진출 시 추가</span>
          </div>
          <div className="flex flex-wrap gap-2">
            {fdaOnlyItems.map((t) => (
              <span key={t} className="inline-flex items-center gap-1.5 rounded-[var(--r-full)]"
                style={{ border: "1px dashed var(--p4)", color: "var(--text)", fontSize: "var(--t-xs)", padding: "4px 10px" }}>
                <span aria-hidden className="inline-block shrink-0 rounded-full" style={{ width: 7, height: 7, background: "var(--p4)" }} />
                {t}
              </span>
            ))}
          </div>
        </section>

        {/* 안내 */}
        <p className="text-text-subtle" style={{ fontSize: "var(--t-xs)", lineHeight: "var(--lh-base)" }}>
          분류 기준: 우리 문서셋(75) 중 EU 고유 문서를 CE 전용으로, 나머지(QMS·설계·위험·생산·기술/성능 증거)를 공통으로 보았습니다.
          MDSAP는 별도 고유 문서보다 ISO 13485 QMS + 국가별 규제 챕터를 단일 심사로 묶는 프로그램입니다. 동일 문서라도 서식·언어·제출처는 스킴별로 다를 수 있습니다.
        </p>
      </div>
    </div>
  );
}

// =====================================================================
// src/data/schemes.ts
// 규제 스킴 간 문서 중복(재사용) 매핑.
// ISO 13485 = QMS 공통 기반. MDSAP = ISO 13485 + 5개국(AU·BR·CA·JP·US) 단일 심사.
// CE(IVDR)·FDA(US)는 그 위에 시장별 문서를 얹는다.
// 우리 문서셋(75)은 IVDR 중심이라 FDA 고유 제출문서는 보유하지 않음(참고로만 표시).
// =====================================================================

import { allLeaves } from "./docTree";

/** CE(IVDR) 전용 — EU 시장 고유 문서(우리 문서셋 내 id). 나머지는 공통 재사용. */
export const ceOnlyDocIds: string[] = [
  "qualification-statement",
  "classification-rationale",
  "conformity-route-plan",
  "tech-doc-toc-gspr",
  "qms-ivdr-matrix",
  "performance-eval-plan",
  "performance-eval-report",
  "clinical-performance-study-plan",
  "declaration-of-conformity",
  "ce-marking-application",
  "ssp",
  "nb-application",
  "prrc",
  "authorised-rep-mandate",
  "importer-distributor",
  "actor-registration",
  "device-registration",
  "udi-assignment",
  "cs-compliance",
  "eurl-batch-verification",
  "cdx-consultation",
  "psur",
  "pmpf-plan",
  "trend-reporting",
  "fsca-recall",
  "pms-report",
];

/** 공통 재사용 문서 = 전체 − CE 전용. (ISO 13485·MDSAP·CE·FDA에 두루 재사용) */
export function sharedDocIds(): string[] {
  const ce = new Set(ceOnlyDocIds);
  return allLeaves()
    .map((l) => l.id)
    .filter((id) => !ce.has(id));
}

/** 이 문서가 CE 외 다른 인증과 중복(재사용)되는가. */
export const isSharedDoc = (id: string): boolean => !ceOnlyDocIds.includes(id);

/** 공통 문서가 겹치는 다른 인증 라벨(CE는 IVDR 기본이라 제외). */
export const overlapSchemes = ["ISO 13485", "MDSAP", "FDA"];

/** FDA(US) 고유 제출문서 — 우리 IVDR 문서셋 밖. 참고 표시용(링크 없음). */
export const fdaOnlyItems: string[] = [
  "510(k) / De Novo / PMA 제출",
  "FDA 시설 등록 · 기기 목록",
  "GUDID (FDA UDI)",
  "US Agent 지정",
  "21 CFR 809·801 라벨링",
  "QMSR (21 CFR 820, ISO 13485 정합)",
];

export const mdsapMarkets = ["호주", "브라질", "캐나다", "일본", "미국(FDA)"];

/** 스킴 메타(라벨·색). */
export const schemes = [
  { id: "iso", name: "ISO 13485", sub: "QMS 국제표준 · 공통 기반", colorVar: "--p3" },
  { id: "mdsap", name: "MDSAP", sub: "ISO 13485 + 5개국 단일 심사", colorVar: "--p5" },
  { id: "ce", name: "CE / IVDR", sub: "EU 시장", colorVar: "--p2" },
  { id: "fda", name: "FDA", sub: "US 시장", colorVar: "--p4" },
];

import { Fragment } from "react";
import { Layers, MapPin, FileText, Repeat2, CalendarClock, ArrowRight } from "lucide-react";
import { phases, stations, transitions } from "../data/stations";
import { allLeaves, leavesForStation } from "../data/docTree";
import { sharedDocIds } from "../data/schemes";

const shortLabel = (title: string) => title.split("—")[0].split("(")[0].trim();

/** IVDR 인증의 전체 구조 — 한 장 인포그래픽(통계 · 5페이즈 흐름 · 핵심 기한). */
export function CertStructure({ onOpen }: { onOpen: (id: number) => void }) {
  const totalDocs = allLeaves().length;
  const shared = sharedDocIds().length;

  const stats = [
    { n: phases.length, label: "페이즈", Icon: Layers, color: "--p1" },
    { n: stations.length, label: "정거장", Icon: MapPin, color: "--p3" },
    { n: totalDocs, label: "문서", Icon: FileText, color: "--p4" },
    { n: shared, label: "공통 재사용", Icon: Repeat2, color: "--p5" },
  ];

  const phaseStations = (pid: string) => stations.filter((s) => s.phase === pid);
  const phaseDocCount = (pid: string) =>
    phaseStations(pid).reduce((a, s) => a + leavesForStation(s.id).length, 0);

  return (
    <section
      aria-label="IVDR 인증의 전체 구조"
      className="rounded-[var(--r-lg)] border"
      style={{ borderColor: "var(--border)", background: "var(--surface)", padding: "var(--s-6)" }}
    >
      {/* 헤더 */}
      <div className="flex items-center gap-2" style={{ marginBottom: "var(--s-1)" }}>
        <span className="inline-flex items-center gap-1.5 rounded-full font-extrabold text-text-on-color" style={{ background: "var(--accent)", fontSize: "var(--t-xs)", padding: "4px 12px" }}>
          전체 구조
        </span>
      </div>
      <h2 className="font-extrabold text-text" style={{ fontSize: "var(--t-2xl)", lineHeight: "var(--lh-tight)" }}>
        IVDR 인증의 전체 구조
      </h2>
      <p className="text-text-muted" style={{ fontSize: "var(--t-base)", marginTop: 4, maxWidth: 720 }}>
        5개 페이즈 · 11개 정거장으로 진행하며, 단계마다 문서를 만든다. 아래는 인증 전체를 한 장에 담은 지도입니다.
      </p>

      {/* 통계 */}
      <div className="grid gap-3" style={{ gridTemplateColumns: "repeat(auto-fit, minmax(140px, 1fr))", marginTop: "var(--s-5)" }}>
        {stats.map((s) => (
          <div key={s.label} className="flex items-center gap-3 rounded-[var(--r-md)] bg-bg" style={{ border: "1px solid var(--border)", boxShadow: "var(--shadow-card)", padding: "var(--s-4)" }}>
            <span className="grid shrink-0 place-items-center rounded-[var(--r-md)]" style={{ width: 44, height: 44, background: `var(${s.color}-tint)` }}>
              <s.Icon size={22} style={{ color: `var(${s.color})` }} aria-hidden />
            </span>
            <div className="min-w-0">
              <div className="font-extrabold text-text" style={{ fontSize: "var(--t-2xl)", lineHeight: 1 }}>{s.n}</div>
              <div className="font-semibold text-text-muted" style={{ fontSize: "var(--t-xs)" }}>{s.label}</div>
            </div>
          </div>
        ))}
      </div>

      {/* 5 페이즈 흐름 */}
      <div className="flex flex-col lg:flex-row lg:items-stretch" style={{ gap: 6, marginTop: "var(--s-6)" }}>
        {phases.map((p, i) => {
          const color = `var(${p.colorVar})`;
          const tint = `var(${p.tintVar})`;
          const sts = phaseStations(p.id);
          return (
            <Fragment key={p.id}>
              <div className="flex-1 rounded-[var(--r-md)]" style={{ background: tint, borderTop: `4px solid ${color}`, padding: "var(--s-4)" }}>
                <div className="flex items-center gap-2">
                  <span className="grid shrink-0 place-items-center rounded-full text-text-on-color font-extrabold" style={{ width: 28, height: 28, background: color, fontSize: "var(--t-sm)" }}>{p.order}</span>
                  <span className="font-extrabold text-text" style={{ fontSize: "var(--t-base)" }}>{p.title}</span>
                </div>
                <div className="flex flex-wrap gap-1.5" style={{ marginTop: "var(--s-3)" }}>
                  {sts.map((s) => (
                    <button
                      key={s.id}
                      type="button"
                      onClick={() => onOpen(s.id)}
                      className="inline-flex items-center gap-1 rounded-[var(--r-full)] bg-bg font-semibold text-text hover:bg-surface"
                      style={{ border: "1px solid var(--border)", fontSize: "var(--t-xs)", padding: "3px 9px" }}
                    >
                      <span className="grid place-items-center rounded-full text-text-on-color font-bold" style={{ width: 15, height: 15, background: color, fontSize: 9 }}>{s.id}</span>
                      {shortLabel(s.title)}
                    </button>
                  ))}
                </div>
                <div className="inline-flex items-center gap-1 rounded-full font-bold" style={{ background: color, color: "var(--text-on-color)", fontSize: "var(--t-xs)", padding: "2px 9px", marginTop: "var(--s-3)" }}>
                  <FileText size={12} aria-hidden /> 문서 {phaseDocCount(p.id)}개
                </div>
              </div>
              {i < phases.length - 1 && (
                <div className="flex items-center justify-center" style={{ color: "var(--text-subtle)" }}>
                  <ArrowRight className="rotate-90 lg:rotate-0" size={18} aria-hidden />
                </div>
              )}
            </Fragment>
          );
        })}
      </div>

      {/* 핵심 기한 */}
      <div className="flex flex-wrap items-center gap-x-4 gap-y-2 rounded-[var(--r-md)]" style={{ background: "var(--bg)", border: "1px solid var(--border)", padding: "var(--s-3) var(--s-4)", marginTop: "var(--s-6)" }}>
        <span className="inline-flex items-center gap-1.5 font-bold text-text" style={{ fontSize: "var(--t-sm)" }}>
          <CalendarClock size={16} style={{ color: "var(--text-muted)" }} aria-hidden /> 핵심 기한
        </span>
        {transitions.map((t) => (
          <span key={t.cls} className="inline-flex items-center gap-1.5" style={{ fontSize: "var(--t-xs)" }}>
            <span className="font-bold text-text">{t.cls}</span>
            <span className="font-mono font-bold" style={{ color: "var(--warning)" }}>{t.deadline}</span>
          </span>
        ))}
        <span className="inline-flex items-center gap-1.5" style={{ fontSize: "var(--t-xs)" }}>
          <span className="font-bold text-text">EUDAMED 의무화</span>
          <span className="font-mono font-bold" style={{ color: "var(--warning)" }}>2026.5.28</span>
        </span>
      </div>
    </section>
  );
}

// =====================================================================
// src/lib/docx.ts
// 워드(.docx) 내보내기 — 전부 브라우저에서 처리(서버 업로드 없음).
//  · generateSampleDocx : 표시자({docTitle}, {#sections}...)가 든 샘플 .docx 생성
//  · fillUploadedDocx   : 업로드한 .docx 자동 판별
//       표시자 있으면 그 자리에 채움(docxtemplater),
//       없으면 문서 끝에 내용을 본문으로 덧붙임(XML 주입).
// =====================================================================

import PizZip from "pizzip";
import Docxtemplater from "docxtemplater";
import { Document, Packer, Paragraph, TextRun, HeadingLevel } from "docx";
import type { DocTemplate } from "../data/documents";
import { prereqKindLabel, difficultyLabel, importanceLabel, leafById } from "../data/docTree";

export const DOCX_MIME =
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document";

export type FillMode = "filled" | "appended";

/** docxtemplater 데이터 객체. 샘플 표시자와 키가 일치한다. */
function buildData(doc: DocTemplate) {
  return {
    docTitle: doc.docTitle,
    purpose: doc.purpose,
    rationale: doc.rationale ?? "",
    refsLine: doc.refs.join(" · "),
    difficulty: doc.difficulty ? difficultyLabel[doc.difficulty] : "",
    importance: doc.importance ? importanceLabel[doc.importance] : "",
    effortTotal: doc.effort?.total ?? "",
    effortGather: doc.effort?.gather ?? "",
    effortContext: doc.effort?.context ?? "",
    effortDraft: doc.effort?.draft ?? "",
    effortReview: doc.effort?.review ?? "",
    effortRa: doc.effort ? String(doc.effort.raRounds) : "",
    prepDocs: (doc.prepDocs ?? []).map((id) => ({
      title: leafById(id)?.title ?? id,
    })),
    knowledge: (doc.knowledge ?? []).map((k) => ({ item: k })),
    prerequisites: (doc.prerequisites ?? []).map((p) => ({
      kind: prereqKindLabel[p.kind],
      label: p.label,
    })),
    sections: doc.sections.map((s) => ({
      heading: s.heading,
      guidance: s.guidance,
      placeholder: s.placeholder,
    })),
    checklist: doc.checklist.map((item) => ({ item })),
  };
}

// ---- 표시자 없는 문서: 끝에 덧붙일 본문 XML 생성 ----
function escXml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function paraXml(
  text: string,
  opts?: { bold?: boolean; size?: number },
): string {
  const runProps =
    opts && (opts.bold || opts.size)
      ? `<w:rPr>${opts.bold ? "<w:b/>" : ""}${
          opts.size ? `<w:sz w:val="${opts.size}"/><w:szCs w:val="${opts.size}"/>` : ""
        }</w:rPr>`
      : "";
  return `<w:p><w:r>${runProps}<w:t xml:space="preserve">${escXml(text)}</w:t></w:r></w:p>`;
}

function buildBodyXml(doc: DocTemplate): string {
  const parts: string[] = [];
  parts.push(paraXml(doc.docTitle, { bold: true, size: 32 }));
  parts.push(paraXml(`목적: ${doc.purpose}`));
  parts.push(paraXml(`근거: ${doc.refs.join(" · ")}`));
  if (doc.difficulty && doc.importance) {
    parts.push(
      paraXml(
        `난이도: ${difficultyLabel[doc.difficulty]} · 중요도: ${importanceLabel[doc.importance]}`,
      ),
    );
  }
  if (doc.effort) {
    parts.push(
      paraXml(
        `예상 소요(추정): ${doc.effort.total} — 자료확보 ${doc.effort.gather} · 맥락이해 ${doc.effort.context} · 작성 ${doc.effort.draft} · 검토 ${doc.effort.review} · RA 피드백 ${doc.effort.raRounds}회`,
      ),
    );
  }
  parts.push(paraXml(""));
  if (doc.rationale) {
    parts.push(paraXml("취지 — 왜 이 문서를 쓰는가", { bold: true, size: 26 }));
    parts.push(paraXml(doc.rationale));
    parts.push(paraXml(""));
  }
  if (doc.prepDocs && doc.prepDocs.length) {
    parts.push(paraXml("미리 만들어두면 좋은 문서", { bold: true, size: 26 }));
    for (const id of doc.prepDocs) parts.push(paraXml(`· ${leafById(id)?.title ?? id}`));
    parts.push(paraXml(""));
  }
  if (doc.knowledge && doc.knowledge.length) {
    parts.push(paraXml("작성 전 알아야 할 것", { bold: true, size: 26 }));
    for (const k of doc.knowledge) parts.push(paraXml(`☐ ${k}`));
    parts.push(paraXml(""));
  }
  if (doc.prerequisites && doc.prerequisites.length) {
    parts.push(paraXml("작성 전 준비물", { bold: true, size: 26 }));
    for (const p of doc.prerequisites) {
      parts.push(paraXml(`☐ (${prereqKindLabel[p.kind]}) ${p.label}`));
    }
    parts.push(paraXml(""));
  }
  for (const s of doc.sections) {
    parts.push(paraXml(s.heading, { bold: true, size: 26 }));
    parts.push(paraXml(`· ${s.guidance}`));
    for (const line of s.placeholder.split("\n")) parts.push(paraXml(line));
    parts.push(paraXml(""));
  }
  parts.push(paraXml("완료 체크리스트", { bold: true, size: 26 }));
  for (const c of doc.checklist) parts.push(paraXml(`☐ ${c}`));
  return parts.join("");
}

const PLACEHOLDER_RE =
  /\{\s*(docTitle|purpose|refsLine|#\s*sections|#\s*checklist)\s*\}/;

/** 업로드한 .docx 자동 판별 → 채움 또는 덧붙임. */
export async function fillUploadedDocx(
  buf: ArrayBuffer,
  doc: DocTemplate,
): Promise<{ blob: Blob; mode: FillMode }> {
  let zip: PizZip;
  try {
    zip = new PizZip(buf);
  } catch {
    throw new Error("파일을 열 수 없습니다. .docx 형식인지 확인해 주세요.");
  }
  const docXml = zip.file("word/document.xml");
  if (!docXml) {
    throw new Error("올바른 .docx 가 아닙니다 (word/document.xml 없음).");
  }
  const xml = docXml.asText();

  if (PLACEHOLDER_RE.test(xml)) {
    // 표시자 채우기
    const dt = new Docxtemplater(zip, {
      paragraphLoop: true,
      linebreaks: true,
    });
    dt.render(buildData(doc));
    const blob = dt.getZip().generate({ type: "blob", mimeType: DOCX_MIME });
    return { blob, mode: "filled" };
  }

  // 끝에 덧붙이기
  const body = buildBodyXml(doc);
  let newXml: string;
  const sectIdx = xml.lastIndexOf("<w:sectPr");
  if (sectIdx !== -1) {
    newXml = xml.slice(0, sectIdx) + body + xml.slice(sectIdx);
  } else {
    newXml = xml.replace("</w:body>", body + "</w:body>");
  }
  zip.file("word/document.xml", newXml);
  const blob = zip.generate({ type: "blob", mimeType: DOCX_MIME });
  return { blob, mode: "appended" };
}

/** 표시자가 든 샘플 .docx 생성(사장님 서식/로고에 표시자만 넣으면 됨). */
export async function generateSampleDocx(doc: DocTemplate): Promise<Blob> {
  const line = (text: string, o?: { bold?: boolean; heading?: (typeof HeadingLevel)[keyof typeof HeadingLevel] }) =>
    new Paragraph({
      heading: o?.heading,
      children: [new TextRun({ text, bold: o?.bold })],
    });

  const children: Paragraph[] = [
    line(`[샘플 템플릿] ${doc.docTitle} — 표시자는 그대로 두고 서식·로고만 편집하세요`, { bold: true }),
    line(""),
    line("{docTitle}", { heading: HeadingLevel.HEADING_1 }),
    line("목적: {purpose}"),
    line("근거: {refsLine}"),
    line("난이도: {difficulty} · 중요도: {importance}"),
    line("예상 소요(추정): {effortTotal} — 자료확보 {effortGather} · 맥락이해 {effortContext} · 작성 {effortDraft} · 검토 {effortReview} · RA 피드백 {effortRa}회"),
    line(""),
    line("취지 — 왜 이 문서를 쓰는가", { heading: HeadingLevel.HEADING_2 }),
    line("{rationale}"),
    line(""),
    line("미리 만들어두면 좋은 문서", { heading: HeadingLevel.HEADING_2 }),
    line("{#prepDocs}"),
    line("· {title}"),
    line("{/prepDocs}"),
    line(""),
    line("작성 전 알아야 할 것", { heading: HeadingLevel.HEADING_2 }),
    line("{#knowledge}"),
    line("- {item}"),
    line("{/knowledge}"),
    line(""),
    line("작성 전 준비물", { heading: HeadingLevel.HEADING_2 }),
    line("{#prerequisites}"),
    line("- [{kind}] {label}"),
    line("{/prerequisites}"),
    line(""),
    line("[아래 sections 블록이 각 섹션마다 반복됩니다]"),
    line("{#sections}"),
    line("{heading}", { bold: true }),
    line("{guidance}"),
    line("{placeholder}"),
    line("{/sections}"),
    line(""),
    line("완료 체크리스트", { heading: HeadingLevel.HEADING_2 }),
    line("{#checklist}"),
    line("- {item}"),
    line("{/checklist}"),
  ];

  const document = new Document({ sections: [{ children }] });
  return Packer.toBlob(document);
}

/** Blob 다운로드 트리거. */
export function downloadBlob(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

import {
  Clock,
  FolderInput,
  Brain,
  PenLine,
  CheckCircle2,
  MessagesSquare,
  type LucideIcon,
} from "lucide-react";
import type { DocEffort } from "../data/docTree";

/** 예상 소요 기간 — 단계별 분해(자료확보·맥락이해·작성·검토) + RA 피드백 횟수. */
export function EffortTimeline({ effort }: { effort: DocEffort }) {
  const phases: { label: string; value: string; Icon: LucideIcon }[] = [
    { label: "자료 확보", value: effort.gather, Icon: FolderInput },
    { label: "맥락 이해", value: effort.context, Icon: Brain },
    { label: "작성", value: effort.draft, Icon: PenLine },
    { label: "검토", value: effort.review, Icon: CheckCircle2 },
  ];

  return (
    <section
      aria-labelledby="effort-heading"
      className="rounded-[var(--r-lg)] border"
      style={{ borderColor: "var(--border)", background: "var(--surface)", padding: "var(--s-5)" }}
    >
      <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
        <span className="grid shrink-0 place-items-center rounded-full" style={{ width: 36, height: 36, background: "var(--p4)" }}>
          <Clock size={19} style={{ color: "#fff" }} aria-hidden />
        </span>
        <h2 id="effort-heading" className="font-extrabold text-text" style={{ fontSize: "var(--t-lg)" }}>
          예상 소요 기간
        </h2>
        <span
          className="rounded-full font-extrabold text-text-on-color"
          style={{ background: "var(--p4)", fontSize: "var(--t-sm)", padding: "3px 14px" }}
        >
          {effort.total}
        </span>
        <span className="text-text-subtle" style={{ fontSize: "var(--t-xs)" }}>
          난이도 기반 추정 · 조직·인력에 따라 가변
        </span>
      </div>

      {/* 단계 분해 */}
      <div
        className="grid gap-2"
        style={{ gridTemplateColumns: "repeat(auto-fit, minmax(130px, 1fr))", marginTop: "var(--s-4)" }}
      >
        {phases.map((p, i) => (
          <div
            key={p.label}
            className="rounded-[var(--r-md)] bg-bg"
            style={{ border: "1px solid var(--border)", padding: "10px 12px" }}
          >
            <div className="flex items-center gap-1.5 text-text-muted">
              <span className="font-bold" style={{ color: "var(--p4)", fontSize: 10 }}>{i + 1}</span>
              <p.Icon size={14} style={{ color: "var(--p4)" }} aria-hidden />
              <span className="font-semibold" style={{ fontSize: "var(--t-xs)" }}>{p.label}</span>
            </div>
            <div className="font-extrabold text-text" style={{ fontSize: "var(--t-base)", marginTop: 4 }}>
              {p.value}
            </div>
          </div>
        ))}
      </div>

      {/* RA 피드백 */}
      <div className="flex items-center gap-2" style={{ marginTop: "var(--s-3)" }}>
        <span
          className="inline-flex items-center gap-1.5 rounded-full font-bold"
          style={{ background: "var(--p4-tint)", color: "var(--p4)", fontSize: "var(--t-sm)", padding: "5px 13px" }}
        >
          <MessagesSquare size={15} aria-hidden />
          RA 피드백 {effort.raRounds}회 반영
        </span>
        <span className="text-text-subtle" style={{ fontSize: "var(--t-xs)" }}>
          검토·수정 반복 포함
        </span>
      </div>
    </section>
  );
}

