import { useState } from "react";
import { Link } from "react-router-dom";
import { FolderTree, FolderOpen, FileText, Sparkles, List, Network, ListOrdered, Blend, Repeat2 } from "lucide-react";
import {
  docTree,
  requirementMeta,
  docTreeStats,
