  refs: string[];
  relatedStationIds: number[];
  relatedConceptSlugs: string[];
}

export const categoryLabel: Record<ConceptCategory, string> = {
  annex: "부속서(Annex)",
  standard: "국제 표준",
  concept: "핵심 개념",
  actor: "행위자·기관",
  deliverable: "산출물 문서",
};

