import { BrowserRouter, Route, Routes } from "react-router-dom";
import { JourneyMap } from "./components/JourneyMap";
import { DocumentWorkspace } from "./components/DocumentWorkspace";
import { DocumentTree } from "./components/DocumentTree";
import { ConceptPage } from "./components/ConceptPage";
import { WikiIndex } from "./components/WikiIndex";

export default function App() {
  // GitHub Pages 하위 경로 배포 대응 (로컬은 '/').
  const basename = import.meta.env.BASE_URL.replace(/\/$/, "");
  return (
    <BrowserRouter basename={basename}>
      <Routes>
        {/* 랜딩 + 딥링크 상세(drawer) */}
        <Route path="/" element={<JourneyMap />} />
        <Route path="/station/:id" element={<JourneyMap />} />
        {/* 문서 트리(마스터 등록부) + 작성 워크스페이스 */}
        <Route path="/documents" element={<DocumentTree />} />
        <Route path="/doc/:id" element={<DocumentWorkspace />} />
        {/* 개념 위키 */}
        <Route path="/wiki" element={<WikiIndex />} />
        <Route path="/wiki/:slug" element={<ConceptPage />} />
        <Route path="*" element={<JourneyMap />} />
      </Routes>
    </BrowserRouter>
  );
}

// =====================================================================
// src/data/stations.ts
// IVDR 여정 콘텐츠 — 부록 A (검증된 규제 사실 포함, 2026.6 기준)
// 글/조항 수정은 이 파일에서만. 컴포넌트 코드와 분리되어 유지보수가 쉽다.
// =====================================================================

export type PhaseId = "p1" | "p2" | "p3" | "p4" | "p5";

export interface Phase {
  id: PhaseId;
  order: number;
  title: string; // "범위 정의"
  subtitle: string; // 페이즈 한 줄 설명
  colorVar: string; // "--p1"
  tintVar: string; // "--p1-tint"
}

/** 상태칩 — 색 단독 금지(IEC 62366): 항상 라벨 텍스트를 동반한다. */
export type TagTone = "neutral" | "info" | "warning" | "danger" | "success";

export interface StationTag {
  label: string;
  tone: TagTone;
}

export interface ForkPath {
  label: string; // "Class A (비멸균)"
  desc: string;
  route: string; // "자가선언 → 바로 CE"
  tone: TagTone; // 분기별 위험/난이도 신호
}

export interface Station {
  id: number; // 1..11
  phase: PhaseId;
  title: string; // "출발점 — 내 제품이 IVD인가?"
  icon: string; // lucide 이름: "target"
  oneLine: string; // 카드 한 줄
