// 1. 폰트 확인
const fonts = await figma.listAvailableFontsAsync();
const pretendard = fonts.filter(f => f.fontName.family === "Pretendard");
const notoSans = fonts.filter(f => f.fontName.family === "Noto Sans KR");
const inter = fonts.filter(f => f.fontName.family === "Inter").map(f => f.fontName.style).slice(0,5);

// 2. 기존 페이지 이름 변경
const pages = figma.root.children;
pages[0].name = "01 · CertHub";

// 3. 추가 페이지 생성
const pageNames = ["02 · IVDR 여정", "03 · ISO 13485 여정", "04 · 문서 트리", "05 · 문서 워크스페이스"];
for (const name of pageNames) {
  const p = figma.createPage();
  p.name = name;
}

return {
  pretendardStyles: pretendard.map(f => f.fontName.style),
  notoSansStyles: notoSans.map(f => f.fontName.style).slice(0, 8),
  interStyles: inter,
  pages: figma.root.children.map(p => p.name)
};

const fonts = await figma.listAvailableFontsAsync();
const pretendard = fonts.filter(f => f.fontName.family === "Pretendard").map(f => f.fontName.style);
const notoSans = fonts.filter(f => f.fontName.family === "Noto Sans KR").map(f => f.fontName.style).slice(0, 8);

// 기존 1페이지 이름 변경
figma.root.children[0].name = "01 · CertHub";

// 추가 2페이지만 생성 (총 3페이지)
const p2 = figma.createPage(); p2.name = "02 · IVDR & ISO 13485 여정";
const p3 = figma.createPage(); p3.name = "03 · 문서 공간";

return {
  pretendardStyles: pretendard,
  notoSansStyles: notoSans,
  pages: figma.root.children.map(p => p.name)
};

const page = figma.root.children[0];
await figma.setCurrentPageAsync(page);

// ── Color helpers ──
const hex = (h) => {
  const v = h.replace('#','');
  return { r: parseInt(v.slice(0,2),16)/255, g: parseInt(v.slice(2,4),16)/255, b: parseInt(v.slice(4,6),16)/255 };
};
const solid = (h, o=1) => ({ type:'SOLID', color: hex(h), opacity: o });

const C = {
  bg:         '#FFFFFF', surface:    '#F5F5F5', surface2:   '#ECEEF1',
  border:     '#E2E5E9', borderS:    '#CDD2D9',
  text:       '#1A1A1A', textMuted:  '#545B66', textSubtle: '#8A8F98',
  onColor:    '#FFFFFF',
  accent:     '#E60044', accentWeak: '#FFE5EE',
  p3:         '#0E7065', p3tint:     '#E7F3F1',
  p1:         '#5B6B85', p1tint:     '#EFF2F7',
};
const F = 'Noto Sans KR';

// ── Load fonts ──
await figma.loadFontAsync({ family: F, style: 'Black' });
await figma.loadFontAsync({ family: F, style: 'Bold' });
await figma.loadFontAsync({ family: F, style: 'Medium' });
await figma.loadFontAsync({ family: F, style: 'Regular' });
await figma.loadFontAsync({ family: F, style: 'Light' });

// ── Wrapper (1440px wide, vertical auto-layout) ──
const wrapper = figma.createAutoLayout('VERTICAL');
wrapper.name = 'CertHub';
wrapper.resize(1440, 100);
wrapper.layoutSizingHorizontal = 'FIXED';
wrapper.primaryAxisSizingMode = 'AUTO';
wrapper.counterAxisSizingMode = 'FIXED';
wrapper.fills = [solid(C.bg)];
wrapper.x = 0; wrapper.y = 0;
wrapper.itemSpacing = 0;

// ── NAV bar (64px) ──
const nav = figma.createAutoLayout('HORIZONTAL');
nav.name = 'Nav';
nav.resize(1440, 64);
nav.layoutSizingHorizontal = 'FILL';
nav.primaryAxisSizingMode = 'FIXED';
nav.counterAxisSizingMode = 'FIXED';
nav.primaryAxisAlignItems = 'SPACE_BETWEEN';
nav.counterAxisAlignItems = 'CENTER';
nav.paddingLeft = 40; nav.paddingRight = 40;
nav.fills = [solid(C.bg)];
nav.strokes = [solid(C.border)];
nav.strokeWeight = 1;
nav.strokeAlign = 'INSIDE';
wrapper.appendChild(nav);
nav.layoutSizingHorizontal = 'FILL';

// Nav logo text
const logo = figma.createText();
logo.characters = 'CertDoc';
logo.fontName = { family: F, style: 'Black' };
logo.fontSize = 18;
logo.fills = [solid(C.text)];
nav.appendChild(logo);

// Nav right pills
const navRight = figma.createAutoLayout('HORIZONTAL');
navRight.name = 'NavRight';
navRight.primaryAxisSizingMode = 'AUTO';
navRight.counterAxisSizingMode = 'AUTO';
navRight.itemSpacing = 8;
navRight.counterAxisAlignItems = 'CENTER';
navRight.fills = [];
nav.appendChild(navRight);

const navItems = ['IVDR 여정', 'ISO 13485', '문서 라이브러리', '개념 위키'];
for (const item of navItems) {
  const pill = figma.createAutoLayout('HORIZONTAL');
  pill.name = item;
  pill.primaryAxisSizingMode = 'AUTO';
  pill.counterAxisSizingMode = 'AUTO';
  pill.paddingLeft = 16; pill.paddingRight = 16;
  pill.paddingTop = 8; pill.paddingBottom = 8;
  pill.cornerRadius = 8;
  pill.fills = [];

  const t = figma.createText();
  t.characters = item;
  t.fontName = { family: F, style: 'Medium' };
  t.fontSize = 14;
  t.fills = [solid(C.textMuted)];
  pill.appendChild(t);
  navRight.appendChild(pill);
}

// ── HERO section ──
const hero = figma.createAutoLayout('VERTICAL');
hero.name = 'Hero';
hero.layoutSizingHorizontal = 'FILL';
hero.primaryAxisSizingMode = 'AUTO';
hero.counterAxisSizingMode = 'FIXED';
hero.counterAxisAlignItems = 'CENTER';
hero.primaryAxisAlignItems = 'CENTER';
hero.paddingTop = 80; hero.paddingBottom = 80;
hero.paddingLeft = 40; hero.paddingRight = 40;
hero.itemSpacing = 24;
hero.fills = [solid(C.bg)];
wrapper.appendChild(hero);
hero.layoutSizingHorizontal = 'FILL';

// Badge chip
const badge = figma.createAutoLayout('HORIZONTAL');
badge.name = 'Badge';
badge.primaryAxisSizingMode = 'AUTO';
badge.counterAxisSizingMode = 'AUTO';
badge.paddingLeft = 16; badge.paddingRight = 16;
badge.paddingTop = 6; badge.paddingBottom = 6;
badge.cornerRadius = 999;
badge.fills = [solid(C.accentWeak)];
const badgeT = figma.createText();
badgeT.characters = '의료기기 인증 문서 작성 플랫폼';
badgeT.fontName = { family: F, style: 'Bold' };
badgeT.fontSize = 13;
badgeT.fills = [solid(C.accent)];
badge.appendChild(badgeT);
hero.appendChild(badge);

// H1
const h1 = figma.createText();
h1.characters = '인증을 선택하세요';
h1.fontName = { family: F, style: 'Black' };
h1.fontSize = 48;
h1.textAlignHorizontal = 'CENTER';
h1.fills = [solid(C.text)];
h1.layoutSizingHorizontal = 'FILL';
hero.appendChild(h1);

// Subtitle
const sub = figma.createText();
sub.characters = 'IVDR · ISO 13485 인증 문서를 체계적으로 작성하세요.\n규제 여정을 단계별로 안내하고 공통 문서를 자동 연결합니다.';
sub.fontName = { family: F, style: 'Regular' };
sub.fontSize = 18;
sub.textAlignHorizontal = 'CENTER';
sub.fills = [solid(C.textMuted)];
sub.lineHeight = { value: 1.65, unit: 'PIXELS' };
h1.layoutSizingHorizontal = 'FILL';
hero.appendChild(sub);

page.appendChild(wrapper);

return { wrapperId: wrapper.id, heroId: hero.id, navId: nav.id };

const page = figma.root.children[0];
await figma.setCurrentPageAsync(page);

const hex = (h) => { const v=h.replace('#',''); return {r:parseInt(v.slice(0,2),16)/255,g:parseInt(v.slice(2,4),16)/255,b:parseInt(v.slice(4,6),16)/255}; };
const solid = (h, o=1) => ({ type:'SOLID', color:hex(h), opacity:o });
const C = {
  bg:'#FFFFFF', surface:'#F5F5F5', border:'#E2E5E9',
  text:'#1A1A1A', textMuted:'#545B66', textSubtle:'#8A8F98', onColor:'#FFFFFF',
  accent:'#E60044', accentWeak:'#FFE5EE',
  p3:'#0E7065', p3tint:'#E7F3F1', p1:'#5B6B85', p1tint:'#EFF2F7',
};
const F = 'Noto Sans KR';

await Promise.all([
  figma.loadFontAsync({family:F,style:'Black'}),
  figma.loadFontAsync({family:F,style:'Bold'}),
  figma.loadFontAsync({family:F,style:'Medium'}),
  figma.loadFontAsync({family:F,style:'Regular'}),
  figma.loadFontAsync({family:F,style:'Light'}),
]);

// ── Wrapper: top-level FIXED (1440px) ──
const wrapper = figma.createAutoLayout('VERTICAL');
wrapper.name = 'CertHub';
wrapper.primaryAxisSizingMode = 'AUTO';
wrapper.counterAxisSizingMode = 'FIXED';
wrapper.resize(1440, 100);
wrapper.fills = [solid(C.bg)];
wrapper.itemSpacing = 0;
wrapper.x = 0; wrapper.y = 0;
page.appendChild(wrapper);

// ── NAV ──
const nav = figma.createAutoLayout('HORIZONTAL');
nav.name = 'Nav';
nav.primaryAxisSizingMode = 'FIXED';
nav.counterAxisSizingMode = 'FIXED';
nav.resize(1440, 64);
nav.primaryAxisAlignItems = 'SPACE_BETWEEN';
nav.counterAxisAlignItems = 'CENTER';
nav.paddingLeft = 40; nav.paddingRight = 40;
nav.fills = [solid(C.bg)];
nav.strokes = [solid(C.border)]; nav.strokeWeight = 1; nav.strokeAlign = 'INSIDE';
wrapper.appendChild(nav);
nav.layoutSizingHorizontal = 'FILL';

const logo = figma.createText();
logo.characters = 'CertDoc';
logo.fontName = {family:F,style:'Black'}; logo.fontSize = 18;
logo.fills = [solid(C.text)];
nav.appendChild(logo);

const navRight = figma.createAutoLayout('HORIZONTAL');
navRight.name = 'NavRight';
navRight.primaryAxisSizingMode = 'AUTO'; navRight.counterAxisSizingMode = 'AUTO';
navRight.itemSpacing = 4; navRight.counterAxisAlignItems = 'CENTER'; navRight.fills = [];
nav.appendChild(navRight);
for (const item of ['IVDR 여정','ISO 13485','문서 라이브러리','개념 위키']) {
  const pill = figma.createAutoLayout('HORIZONTAL');
  pill.primaryAxisSizingMode='AUTO'; pill.counterAxisSizingMode='AUTO';
  pill.paddingLeft=12; pill.paddingRight=12; pill.paddingTop=8; pill.paddingBottom=8;
  pill.cornerRadius=8; pill.fills=[];
  const t = figma.createText();
  t.characters=item; t.fontName={family:F,style:'Medium'}; t.fontSize=14; t.fills=[solid(C.textMuted)];
  pill.appendChild(t); navRight.appendChild(pill);
}

