// Helper: create a certification card
const makeCard = (opts) => {
  const {name, colorMain, colorTint, tag, title, desc, phases, docs, done, inProgress} = opts;

  const card = figma.createAutoLayout('VERTICAL');
  card.name=name; card.resize(580,100);
  card.primaryAxisSizingMode='AUTO'; card.counterAxisSizingMode='FIXED';
  card.paddingTop=40; card.paddingBottom=40; card.paddingLeft=40; card.paddingRight=40;
  card.itemSpacing=24;
  card.cornerRadius=20;
  card.fills=[solid(C.bg)];
  card.effects=[{type:'DROP_SHADOW',color:{r:0.063,g:0.094,b:0.157,a:0.1},offset:{x:0,y:4},radius:20,spread:0,visible:true,blendMode:'NORMAL'}];
  card.strokes=[solid(C.border)]; card.strokeWeight=1; card.strokeAlign='INSIDE';

  // Color top stripe
  const stripe = figma.createRectangle();
  stripe.name='Stripe'; stripe.resize(580,6); stripe.fills=[solid(colorMain)];
  stripe.cornerRadius=16;
  card.appendChild(stripe);
  stripe.layoutSizingHorizontal='FILL';

  // Header row: icon placeholder + tag
  const headerRow = figma.createAutoLayout('HORIZONTAL');
  headerRow.name='HeaderRow'; headerRow.primaryAxisSizingMode='FIXED'; headerRow.counterAxisSizingMode='AUTO';
  headerRow.resize(500,100); headerRow.primaryAxisAlignItems='SPACE_BETWEEN'; headerRow.counterAxisAlignItems='CENTER';
  headerRow.fills=[];
  card.appendChild(headerRow);
  headerRow.layoutSizingHorizontal='FILL';

  // Icon circle
  const iconCircle = figma.createEllipse();
  iconCircle.name='Icon'; iconCircle.resize(48,48);
  iconCircle.fills=[solid(colorTint)];
  headerRow.appendChild(iconCircle);

  // Tag badge
  const tagBadge = figma.createAutoLayout('HORIZONTAL');
  tagBadge.primaryAxisSizingMode='AUTO'; tagBadge.counterAxisSizingMode='AUTO';
  tagBadge.paddingLeft=12; tagBadge.paddingRight=12; tagBadge.paddingTop=5; tagBadge.paddingBottom=5;
  tagBadge.cornerRadius=999; tagBadge.fills=[solid(colorTint)];
  const tagT = figma.createText();
  tagT.characters=tag; tagT.fontName={family:F,style:'Bold'}; tagT.fontSize=12; tagT.fills=[solid(colorMain)];
  tagBadge.appendChild(tagT); headerRow.appendChild(tagBadge);

  // Title
  const titleT = figma.createText();
  titleT.characters=title; titleT.fontName={family:F,style:'Black'}; titleT.fontSize=28;
  titleT.fills=[solid(C.text)]; titleT.textAutoResize='HEIGHT'; titleT.resize(500,100);
  card.appendChild(titleT);
  titleT.layoutSizingHorizontal='FILL';

  // Desc
  const descT = figma.createText();
  descT.characters=desc; descT.fontName={family:F,style:'Regular'}; descT.fontSize=15;
  descT.fills=[solid(C.textMuted)]; descT.lineHeight={value:1.65,unit:'PIXELS'};
  descT.textAutoResize='HEIGHT'; descT.resize(500,100);
  card.appendChild(descT);
  descT.layoutSizingHorizontal='FILL';

  // Divider
  const div = figma.createRectangle();
  div.name='Divider'; div.resize(500,1); div.fills=[solid(C.border)];
  card.appendChild(div);
  div.layoutSizingHorizontal='FILL';

  // Stats row
  const statsRow = figma.createAutoLayout('HORIZONTAL');
  statsRow.name='Stats'; statsRow.primaryAxisSizingMode='FIXED'; statsRow.counterAxisSizingMode='AUTO';
  statsRow.resize(500,100); statsRow.itemSpacing=24; statsRow.fills=[];
  card.appendChild(statsRow);
  statsRow.layoutSizingHorizontal='FILL';

  const stats = [{label:'페이즈',val:phases},{label:'전체 문서',val:docs},{label:'완료',val:done},{label:'작성 중',val:inProgress}];
  for (const s of stats) {
    const col = figma.createAutoLayout('VERTICAL');
    col.primaryAxisSizingMode='AUTO'; col.counterAxisSizingMode='AUTO';
    col.itemSpacing=2; col.fills=[];
    statsRow.appendChild(col);
    const valT = figma.createText();
    valT.characters=String(s.val); valT.fontName={family:F,style:'Black'}; valT.fontSize=22;
    valT.fills=[solid(colorMain)];
    col.appendChild(valT);
    const lblT = figma.createText();
    lblT.characters=s.label; lblT.fontName={family:F,style:'Regular'}; lblT.fontSize=12;
    lblT.fills=[solid(C.textSubtle)];
    col.appendChild(lblT);
  }

  // CTA button
  const cta = figma.createAutoLayout('HORIZONTAL');
  cta.name='CTA'; cta.primaryAxisSizingMode='FIXED'; cta.counterAxisSizingMode='AUTO';
  cta.resize(500,52); cta.primaryAxisAlignItems='CENTER'; cta.counterAxisAlignItems='CENTER';
  cta.cornerRadius=12; cta.fills=[solid(colorMain)];
  card.appendChild(cta);
  cta.layoutSizingHorizontal='FILL';
  const ctaT = figma.createText();
  ctaT.characters='여정 시작하기 →'; ctaT.fontName={family:F,style:'Bold'}; ctaT.fontSize=15;
  ctaT.fills=[solid(C.onColor)]; ctaT.textAlignHorizontal='CENTER';
  cta.appendChild(ctaT);

  return card;
};

