// Fix: lineHeight should be PERCENT (165%) not PIXELS (1.65px)
// Find all TEXT nodes with wrong line height
const allTexts = figma.currentPage.findAllWithCriteria({types:['TEXT']});
const fixed = [];
for (const t of allTexts) {
  // Check if lineHeight is set (non-AUTO)
  const lh = t.lineHeight;
  if (lh && lh.unit === 'PIXELS' && lh.value < 10) {
    // This is wrong (1.65px instead of 165%)
    await figma.loadFontAsync(t.fontName);
    t.lineHeight = { value: 165, unit: 'PERCENT' };
    fixed.push(t.name || t.characters.slice(0,20));
  }
}

return { fixed };

