/* =====================================================================
   IVDR 여정 위키 — Design Tokens (v1)
   design-principles 스킬 EXPORT 모드 산출물
   체계: 70:25:5 VMD + 8pt 그리드 + WCAG AAA + IEC 62366(색+아이콘+라벨)
   모드: Light (콘텐츠 가독성 우선). Dark는 하단 주석 참조.
   ===================================================================== */

:root {
  /* ---- 70:25:5 기본 (면적 비율) ---- */
  --bg:            #FFFFFF;  /* 70% — 페이지 배경 */
  --surface:       #F5F5F5;  /* 25% — 카드·패널 */
  --surface-2:     #ECEEF1;  /*       — 중첩 표면 */
  --border:        #E2E5E9;
  --border-strong: #CDD2D9;

  /* ---- 텍스트 (AAA 우선) ---- */
  --text:          #1A1A1A;  /* 본문 (on white ≈ 16:1) */
  --text-muted:    #545B66;  /* 보조 (≈ 7:1, AAA) */
  --text-subtle:   #8A8F98;  /* 비필수만 사용 (메타·캡션) */
  --text-on-color: #FFFFFF;

  /* ---- ACCENT 5% — SU Red ----
     ⚠ 단 두 가지 의미로만: ① 현재 위치(여정 지도) ② Primary CTA.
     페이즈/상태 구분에는 절대 쓰지 않는다 (액센트 단일성 유지). */
  --accent:        #E60044;
  --accent-hover:  #C7003B;
  --accent-weak:   #FFE5EE;

  /* ---- 페이즈 색 (정보 식별용 · subordinate 레벨, accent 아님) ----
     각 페이즈는 솔리드(태그/마커) + 틴트(배경 밴드) 쌍으로 사용.
     모든 솔리드는 흰 텍스트 AAA, 틴트 위 본문은 --text 사용. */
  --p1:      #5B6B85;  --p1-tint: #EFF2F7;  /* Phase 1 · 범위 정의   */
  --p2:      #A85510;  --p2-tint: #FBF1E6;  /* Phase 2 · 분류·경로(결정) */
  --p3:      #0E7065;  --p3-tint: #E7F3F1;  /* Phase 3 · 증거 구축   */
  --p4:      #4138B8;  --p4-tint: #ECEBFA;  /* Phase 4 · 적합성 인증 */
  --p5:      #1C7A3E;  --p5-tint: #E8F4EC;  /* Phase 5 · 시장·유지   */

  /* ---- 의미 색 (상태/위험 — 감정 위계 녹→황→적) ---- */
  --success:  #1C7A3E;  --success-bg: #E8F4EC;
  --warning:  #A85510;  --warning-bg: #FBF1E6;
  --danger:   #B3251D;  --danger-bg:  #FBEAE8;
  --info:     #1D4ED8;  --info-bg:    #E8EEFC;

  /* ---- Spacing — 8pt 그리드 (4pt half-step 허용) ---- */
  --s-1: 4px;  --s-2: 8px;  --s-3: 12px; --s-4: 16px;
  --s-6: 24px; --s-8: 32px; --s-12: 48px; --s-16: 64px;

  /* ---- Radius ---- */
  --r-sm: 6px; --r-md: 10px; --r-lg: 16px; --r-full: 999px;

  /* ---- Type scale (modular 1.25) ---- */
  --t-xs:   12px;  /* 캡션·각주 */
  --t-sm:   14px;  /* 메타·라벨 */
  --t-base: 16px;  /* 본문 (v0의 15px보다 키움 = 가독성) */
  --t-lg:   20px;  /* 카드 제목 */
  --t-xl:   25px;  /* 섹션 제목 */
  --t-2xl:  31px;  /* 페이지 H1 */
  --t-3xl:  39px;  /* 히어로 */
  --lh-tight: 1.3;
  --lh-base:  1.65;

  --font-sans: "Pretendard", "Apple SD Gothic Neo", "Noto Sans KR", system-ui, sans-serif;
  --font-mono: "Space Mono", "D2Coding", monospace;

  /* ---- Elevation (평평하게 — 카드 분리만) ---- */
  --shadow-card: 0 1px 2px rgba(16,24,40,.06), 0 1px 3px rgba(16,24,40,.09);
  --shadow-pop:  0 8px 24px rgba(16,24,40,.12);

  /* ---- Layout ---- */
  --max-w: 1120px;
  --grid-cols: 12;
  --gutter: 24px;
  --margin: 24px;

  /* ---- Safety (IEC 62366 정신) ---- */
  --touch-min: 48px;   /* 인터랙티브 요소 최소 크기 */
  --focus-ring: 0 0 0 3px rgba(230,0,68,.35);
}

/* =====================================================================
   Dark 모드가 필요하면 아래를 적용 (data-theme="dark"):
   --bg:#1A1A1A; --surface:#2A2A2A; --surface-2:#333; --border:#3A3A3A;
   --text:#F5F5F5; --text-muted:#C7CBD1; --accent:#FF5577;
   페이즈 틴트는 솔리드의 18% 알파로 대체.
   단, 장문 위키는 Light가 글랜서빌리티에 유리하므로 Light를 기본 권장.
   ===================================================================== */

@import "tailwindcss";
@import "./styles/tokens.css";

/* ---------------------------------------------------------------------
   tokens.css 의 CSS 변수를 Tailwind v4 테마에 연결.
   @theme inline → 생성되는 유틸리티가 var(--token) 을 그대로 참조하므로
   tokens.css 한 곳만 고치면 전체가 따라온다. (유지보수 핵심)
   --------------------------------------------------------------------- */
@theme inline {
  /* 색 — 70:25:5 + 페이즈 + 의미 */
  --color-bg: var(--bg);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-border: var(--border);
  --color-border-strong: var(--border-strong);

  --color-text: var(--text);
  --color-text-muted: var(--text-muted);
  --color-text-subtle: var(--text-subtle);
  --color-text-on-color: var(--text-on-color);

  --color-accent: var(--accent);
  --color-accent-hover: var(--accent-hover);
  --color-accent-weak: var(--accent-weak);

  --color-p1: var(--p1);
  --color-p1-tint: var(--p1-tint);
  --color-p2: var(--p2);
  --color-p2-tint: var(--p2-tint);
  --color-p3: var(--p3);
  --color-p3-tint: var(--p3-tint);
  --color-p4: var(--p4);
  --color-p4-tint: var(--p4-tint);
  --color-p5: var(--p5);
  --color-p5-tint: var(--p5-tint);

  --color-success: var(--success);
  --color-success-bg: var(--success-bg);
  --color-warning: var(--warning);
  --color-warning-bg: var(--warning-bg);
  --color-danger: var(--danger);
  --color-danger-bg: var(--danger-bg);
  --color-info: var(--info);
  --color-info-bg: var(--info-bg);

  /* 타이포 스케일 */
  --text-xs: var(--t-xs);
  --text-sm: var(--t-sm);
  --text-base: var(--t-base);
  --text-lg: var(--t-lg);
  --text-xl: var(--t-xl);
  --text-2xl: var(--t-2xl);
  --text-3xl: var(--t-3xl);

  --font-sans: var(--font-sans);
  --font-mono: var(--font-mono);

  /* 8pt 간격 (Tailwind spacing 유틸 보강) */
  --spacing-1: var(--s-1);
  --spacing-2: var(--s-2);
  --spacing-3: var(--s-3);
  --spacing-4: var(--s-4);
  --spacing-6: var(--s-6);
  --spacing-8: var(--s-8);
  --spacing-12: var(--s-12);
  --spacing-16: var(--s-16);

  /* Radius */
  --radius-sm: var(--r-sm);
  --radius-md: var(--r-md);
  --radius-lg: var(--r-lg);
  --radius-full: var(--r-full);

  /* Elevation */
  --shadow-card: var(--shadow-card);
  --shadow-pop: var(--shadow-pop);
}

/* ---- 베이스 ---- */
html {
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--t-base);
  line-height: var(--lh-base);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

* {
  box-sizing: border-box;
}

/* ---- 포커스 링 (접근성) — accent 사용은 포커스/현재위치/CTA 한정 ---- */
:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-radius: var(--r-sm);
}

/* drawer 슬라이드 — 150~200ms ease (과한 모션 금지) */
@keyframes ivdr-slide {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (min-width: 640px) {
  @keyframes ivdr-slide {
    from {
      opacity: 0;
      transform: translateX(24px);
    }
    to {
      opacity: 1;
      transform: translateX(0);
    }
  }
}

/* 모션 줄이기 선호 존중 */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

